package com.example.commerce.order;
import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import java.util.UUID;import org.slf4j.MDC;import org.springframework.core.Ordered;import org.springframework.core.annotation.Order;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;
@Component @Order(Ordered.HIGHEST_PRECEDENCE) public class CorrelationIdFilter extends OncePerRequestFilter{static final String HEADER="X-Correlation-ID";@Override protected void doFilterInternal(HttpServletRequest request,HttpServletResponse response,FilterChain chain)throws ServletException,IOException{var supplied=request.getHeader(HEADER);var id=supplied!=null&&supplied.length()<=64&&supplied.matches("[A-Za-z0-9._-]+")?supplied:UUID.randomUUID().toString().replace("-","");response.setHeader(HEADER,id);MDC.put("correlationId",id);try{chain.doFilter(request,response);}finally{MDC.remove("correlationId");}}}
